{"path":"/var/folders/09/c3s_t1kd4m91p7yltrx08snw0000gn/T/sv-be39ea8336884b3583fe3e48d5cc045a/Program.cs.new","file_text":"using Markout;

// A package collection tool produced this raw data — it carries no output formatting.
// Diagnostics is the deepest / most expensive detail, so we only gather it when a
// requested section actually needs it (verbosity backpressure).
var raw = new RawPackage(
    Id: "Serilog",
    Downloads: 500_000_000,
    Dependencies: new() { new("Serilog.Sinks.Console", "5.0.0") },
    Diagnostics: new() { new("warning", "transitive version conflict") });

// ── 1. Quiet: title + scalars only, no detail sections. ─────────────────────
Render("Quiet report", raw, Array.Empty<string>());

// ── 2. Diagnostics only: promotes verbosity so Diagnostics is COLLECTED, ─────
//        yet renders Diagnostics and NOT Dependencies.
Render("Diagnostics-only report", raw, new[] { Sections.Diagnostics });

// ── 3. Detailed: both Dependencies and Diagnostics. ──────────────────────────
Render("Detailed report", raw, new[] { Sections.Dependencies, Sections.Diagnostics });

static void Render(string label, RawPackage raw, string[] requestedSections)
{
    // Resolve the requested sections first, then raise verbosity to satisfy them,
    // THEN collect — so a narrow request stays cheap.
    var required = RequiredVerbosity(requestedSections);
    var model = Collect(raw, required);

    var options = new MarkoutWriterOptions
    {
        IncludeSections = new HashSet<string>(requestedSections),
    };

    Console.WriteLine($"===== {label} (verbosity: {required}) =====");
    MarkoutSerializer.Serialize(model, Console.Out, ReportContext.Default, options);
    Console.WriteLine();
}

// Requested sections drive the effective verbosity. Diagnostics is the deepest detail.
static Verbosity RequiredVerbosity(string[] sections)
{
    var v = Verbosity.Quiet;
    foreach (var s in sections)
    {
        if (s == Sections.Diagnostics) v = (Verbosity)Math.Max((int)v, (int)Verbosity.Detailed);
        else if (s == Sections.Dependencies) v = (Verbosity)Math.Max((int)v, (int)Verbosity.Normal);
    }
    return v;
}

// Populate only as deep as the verbosity requires; Markout renders whatever the model carries.
static PackageReport Collect(RawPackage raw, Verbosity verbosity) => new()
{
    Id = raw.Id,
    Downloads = raw.Downloads,
    Dependencies = verbosity >= Verbosity.Normal
        ? raw.Dependencies.Select(d => new Dep { Name = d.Name, Version = d.Version }).ToList()
        : null,
    Diagnostics = verbosity >= Verbosity.Detailed
        ? raw.Diagnostics.Select(d => new Diagnostic { Level = d.Level, Text = d.Text }).ToList()
        : null,
};

enum Verbosity { Quiet, Normal, Detailed }

static class Sections
{
    public const string Dependencies = "Dependencies";
    public const string Diagnostics = "Diagnostics";
}

// Raw, unformatted data from the collection tool.
record RawPackage(string Id, long Downloads, List<RawDep> Dependencies, List<RawDiagnostic> Diagnostics);
record RawDep(string Name, string Version);
record RawDiagnostic(string Level, string Text);

// ── One model definition, rendered three ways. ───────────────────────────────
[MarkoutSerializable(TitleProperty = nameof(Id), FieldLayout = FieldLayout.Inline)]
public sealed class PackageReport
{
    public string Id { get; init; } = "";

    [MarkoutDisplayFormat("{0:N0} downloads")]
    public long Downloads { get; init; }

    [MarkoutSection(Name = Sections.Dependencies)]
    public List<Dep>? Dependencies { get; init; }

    [MarkoutSection(Name = Sections.Diagnostics)]
    public List<Diagnostic>? Diagnostics { get; init; }
}

public sealed class Dep { public string Name { get; init; } = ""; public string Version { get; init; } = ""; }

public sealed class Diagnostic { public string Level { get; init; } = ""; public string Text { get; init; } = ""; }

[MarkoutContext(typeof(PackageReport))]
[MarkoutContext(typeof(Dep))]
[MarkoutContext(typeof(Diagnostic))]
public partial class ReportContext : MarkoutSerializerContext { }
"}
